
const LAB_DIRS=[[0,-1],[1,0],[0,1],[-1,0]];
function labNeighbour(i,dir,w,h=w){const [dx,dy]=LAB_DIRS[dir],x=i%w+dx,y=Math.floor(i/w)+dy;return x<0||x>=w||y<0||y>=h?-1:y*w+x;}
function labSnakePath(w){return Array.from({length:w*w},(_,i)=>Math.floor(i/w)*w+(Math.floor(i/w)%2?w-1-i%w:i%w));}
function labPathBoard(d,render){return labGrid(Array.from({length:d.w*d.w},(_,i)=>i),d.w,i=>'<span class="lab-path-cell '+(d.walls?.includes(i)?'lab-wall':'')+'">'+render(i)+'</span>');}
function labPipeConnected(d){let at=d.start,entry=3,seen=[];for(let k=0;k<d.board.length;k++){if(seen.includes(at))return false;seen.push(at);const dirs=d.board[at];if(!dirs.includes(entry))return false;const exit=dirs.find(x=>x!==entry);if(at===d.goal&&exit===1)return true;at=labNeighbour(at,exit,d.w);if(at<0)return false;entry=(exit+2)%4;}return false;}
LAB_ENGINES.path={
 init(c,seed){const v=c.variant,r=labRand(seed*7919),d={w:5,pos:0,goal:24,walls:[],trail:[0],undo:[],steps:0};
 if(['connect','sequence','tail','spots'].includes(v)){d.solution=labSnakePath(5);if(seed%2)d.solution.reverse();d.trail=[d.solution[0]];d.pos=d.solution[0];d.goal=d.solution.at(-1);d.clues={};d.solution.forEach((i,k)=>{if(k%6===0||k===24)d.clues[i]=v==='sequence'&&seed%3===0?25-k:k+1;});d.desc=v==='sequence'&&seed%3===0;d.budget=24;}
 if(v==='knight'){d.w=5;d.pos=0;d.route=[0,7,4,13,24];d.goal=24;d.gems=[7,4,13];d.piece='knight';d.walls=[2,6,8,16,18,22];}
 if(v==='coordinate'){d.targets=labShuffle(Array.from({length:25},(_,i)=>i),r).slice(0,5);d.found=[];}
 if(v==='snake'){d.items={'2':2+seed%3,'14':-(1+seed%2),'22':3};d.target=Object.values(d.items).reduce((a,b)=>a+b,0);d.total=0;d.body=[0];d.walls=[6,8,16,18];}
 if(v==='step'){d.walls=[6,7,8,16,17,18];d.budget=4;d.checkpoints=[4,14,24];d.goal=24;}
 if(v==='paint'){d.walls=[5,6,7,8,16,17,18,19];d.painted=[0];}
 if(v==='maze'){d.walls=[6,7,8,16,17,18];d.pos=0;d.goal=24;d.tilt=0;}
 if(['pipes','rails','unroll'].includes(v)){d.w=4;d.start=0;d.goal=15;const route=[0,1,5,4,8,9,10,6,7,11,15];d.board=Array.from({length:16},()=>[0,2]);for(let k=0;k<route.length;k++){const i=route[k],prev=k?route[k-1]:-1,next=k<route.length-1?route[k+1]:16;const dir=j=>[0,1,2,3].find(x=>labNeighbour(i,x,4)===j);d.board[i]=[k?dir(prev):3,k===route.length-1?1:dir(next)];}d.solution=d.board.map(x=>[...x]);d.rotations=d.board.map(()=>Math.floor(r()*4));d.board=d.board.map((a,i)=>a.map(n=>(n+d.rotations[i])%4));d.selected=null;if(v==='unroll'){d.board=d.solution.map(x=>[...x]);d.swaps=[];for(let k=0;k<16;k++){const at=Math.floor(r()*16),opts=LAB_DIRS.map((_,dir)=>labNeighbour(at,dir,4)).filter(i=>i>=0),to=opts[Math.floor(r()*opts.length)];[d.board[at],d.board[to]]=[d.board[to],d.board[at]];d.swaps.push([at,to]);}}}
 if(v==='laser'){d.w=5;d.mirrors={4:seed%2?'\\':'/',24:seed%2?'/':'\\'};d.crystals=[14,22];d.beam=[];d.walls=[6,8,16,18];}
 return d;
 },
 render(d,c){const v=c.variant;if(['pipes','rails','unroll'].includes(v)){const glyph=a=>{const key=[...a].sort().join('');return {'02':'┃','13':'━','01':'┗','12':'┏','23':'┓','03':'┛'}[key];};return '<p>Connect the entrance at top left to the exit at bottom right. '+(v==='unroll'?'Select two adjacent tiles to swap their tracks.':'Tap a track to rotate it.')+'</p>'+labGrid(d.board,d.w,(a,i)=>'<span class="lab-pipe '+(i===d.start||i===d.goal?'lab-fixed':'')+'">'+glyph(a)+'</span>')+labButton('flow',v==='rails'?'Run the train 🚂':'Release the ball ●');}
 if(v==='laser')return '<p>Light every crystal. Tap a mirror to flip it, then fire the beam.</p>'+labPathBoard(d,i=>d.mirrors[i]|| (i===0?'🔦':d.crystals.includes(i)?'💎':d.beam.includes(i)?'✦':'·'))+labButton('fire','Fire laser');
 if(v==='coordinate'){const target=d.targets[d.found.length];return '<div class="lab-callout">Find ('+(target%5+1)+', '+(5-Math.floor(target/5))+') · '+d.found.length+'/5</div><p>x runs left → right; y runs bottom → top.</p>'+labPathBoard(d,i=>d.found.includes(i)?'💎':'<small>('+(i%5+1)+','+(5-Math.floor(i/5))+')</small>');}
 if(['connect','sequence','tail','spots'].includes(v))return '<p>'+(v==='tail'?'Grow one tail through all 25 spaces.':v==='spots'?'Spend exactly 24 steps to fill every spot.':'Visit every square once, passing the numbered clues in order.')+' Tap an adjacent square; tap the previous square to undo.</p><div class="lab-callout">'+d.trail.length+' / 25 '+(d.desc?'· Count down from 25':'')+'</div>'+labPathBoard(d,i=>i===d.pos?'●':d.clues[i]!==undefined?d.clues[i]:d.trail.includes(i)?'•':'·')+labButton('undo','Undo step');
 return '<p>'+({snake:'Collect every signed fruit. Reach the flag with the target sum; avoid your growing tail.',step:'You have four steps. Reach a checkpoint to refill them.',paint:'Slide until a wall stops you. Paint every reachable square.',knight:'Move like a chess knight: two squares then one across. Collect all gems and reach the flag.',maze:'Tilt the maze to roll the ball into the flag.'})[v]+'</p>'+(v==='snake'?'<div class="lab-callout">Total '+d.total+' / '+d.target+'</div>':v==='step'?'<div class="lab-callout">'+d.budget+' steps left</div>':'')+labPathBoard(d,i=>i===d.pos?(v==='snake'?'🐍':v==='knight'?'♘':'●'):i===d.goal&&v!=='paint'?'🏁':d.items?.[i]!==undefined?String(d.items[i]):d.gems?.includes(i)?'💎':d.checkpoints?.includes(i)?'⚑':d.body?.includes(i)?'🟩':d.painted?.includes(i)?'🟣':'·')+(v==='knight'?'':labOptions('move',['↑','→','↓','←']))+labButton('undo','Undo move');
 },
 action(d,a,n,c){const v=c.variant;if(a==='undo'&&d.undo.length){Object.assign(d,JSON.parse(d.undo.pop()));return;}const save=()=>{const copy={...d};delete copy.undo;d.undo.push(JSON.stringify(copy));};
 if(['pipes','rails','unroll'].includes(v)){if(a==='cell'&&n>=0&&n<16){if(v==='unroll'){if(d.selected===null)d.selected=n;else{if(labAdjacent(d.selected,n,4))[d.board[d.selected],d.board[n]]=[d.board[n],d.board[d.selected]];d.selected=null;}}else d.board[n]=d.board[n].map(x=>(x+1)%4);game.session.moves++;}if(a==='flow'){if(labPipeConnected(d))labWin('A clear route from start to finish!');else labMiss('The route leaks or stops. Check the joins.');}return;}
 if(v==='laser'){if(a==='cell'&&d.mirrors[n])d.mirrors[n]=d.mirrors[n]==='/'?'\\':'/';if(a==='fire'){let pos=0,dir=1,seen=[];d.beam=[];while(true){const key=pos+':'+dir;if(seen.includes(key))break;seen.push(key);d.beam.push(pos);if(d.mirrors[pos])dir=d.mirrors[pos]==='/'?[1,0,3,2][dir]:[3,2,1,0][dir];pos=labNeighbour(pos,dir,5);if(pos<0||d.walls.includes(pos))break;}game.session.moves++;if(d.crystals.every(i=>d.beam.includes(i)))labWin('Every crystal is shining!');else labMiss('Some crystals are still dark. Change the mirrors.');}return;}
 if(v==='coordinate'&&a==='cell'){if(n===d.targets[d.found.length]){d.found.push(n);game.session.moves++;if(d.found.length===5)labWin('Five treasures found with coordinates!');}else labMiss('Check x first, then count y up from the bottom.');return;}
 if(['connect','sequence','tail','spots'].includes(v)&&a==='cell'){if(n===d.trail.at(-2)){d.trail.pop();d.pos=n;return;}if(n<0||n>=25||d.trail.includes(n)||!labAdjacent(n,d.pos,5))return;const next=d.desc?25-d.trail.length:d.trail.length+1;if(d.clues[n]!==undefined&&d.clues[n]!==next){labMiss('Reach this clue at step '+d.clues[n]+'.');return;}save();d.trail.push(n);d.pos=n;game.session.moves++;if(d.trail.length===25)labWin('A complete unbroken path!');return;}
 if(v==='knight'&&a==='cell'){const dx=Math.abs(n%5-d.pos%5),dy=Math.abs(Math.floor(n/5)-Math.floor(d.pos/5));if(dx*dy!==2||d.walls.includes(n))return;save();d.pos=n;d.gems=d.gems.filter(i=>i!==n);game.session.moves++;if(n===d.goal&&!d.gems.length)labWin('Knight mission complete!');return;}
 if(a!=='move'||n<0||n>3)return;let next=labNeighbour(d.pos,n,5);if(next<0||d.walls.includes(next))return;save();if(v==='snake'){if(d.body.includes(next)&&next!==d.body.at(-1)){d.undo.pop();labMiss('Your tail blocks that square.');return;}d.body.unshift(next);if(d.items[next]!==undefined){d.total+=d.items[next];delete d.items[next];}else d.body.pop();d.pos=next;if(next===d.goal&&!Object.keys(d.items).length&&d.total===d.target)labWin('A perfectly balanced snake!');}
 if(v==='step'){d.pos=next;d.budget--;if(d.checkpoints.includes(next))d.budget=4;if(next===d.goal)labWin('Checkpoint trail complete!');else if(d.budget===0)labLose('Out of steps! Try reaching a flag sooner.');}
 if(v==='paint'||v==='maze'){while(next>=0&&!d.walls.includes(next)){d.pos=next;if(v==='paint'&&!d.painted.includes(next))d.painted.push(next);next=labNeighbour(d.pos,n,5);}if(v==='paint'&&d.painted.length===25-d.walls.length)labWin('Every corridor is painted!');if(v==='maze'&&d.pos===d.goal)labWin('The ball reached its goal!');}game.session.moves++;
 }
};
